class Animal {
    String nom;
    Animal(String nom) { this.nom = nom; }
    void parler() { System.out.println(nom + " fait un son"); }
}

class Chien extends Animal {
    Chien(String nom) { super(nom); }

    @Override
    void parler() {
        System.out.println(nom + " dit : Waf !");
    }
}

class Chat extends Animal {
    Chat(String nom) { super(nom); }

    @Override
    void parler() {
        System.out.println(nom + " dit : Miaou !");
    }
}

// Polymorphisme
Animal a = new Chien("Rex");
a.parler(); // Rex dit : Waf !
